"""Begriffe zum Einheitlichen Patentgericht (EPGÜ und VerfO). Felder wie knowledge/concepts.py;
`norms` in der Zitierweise `Art. 33 Abs. 1 EPGÜ` / `R. 19.1 VerfO`; `ipwiki` bleibt leer."""

def c(id, label, kategorie, definition, erlaeuterung, norms=(), cases=(), related=(), quellen=()):
    """`quellen`: Seiten-IDs der UP-Richtlinien (einheitspatent.UP_RICHTLINIEN), Kante `documented_in`."""
    return dict(id=id, label=label, kategorie=kategorie, definition=definition, erlaeuterung=erlaeuterung,
                norms=list(norms), cases=list(cases), ipwiki=[], related=list(related), quellen=list(quellen))


